var ResultHelpers = {
  ok(data) {
    return { success: true, data };
  },
  err(error2) {
    return { success: false, error: error2 };
  },
  isOk(result) {
    return result.success === true;
  },
  isErr(result) {
    return result.success === false;
  },
  map(result, fn) {
    if (result.success) {
      return { success: true, data: fn(result.data) };
    }
    return result;
  },
  mapErr(result, fn) {
    if (!result.success) {
      return { success: false, error: fn(result.error) };
    }
    return result;
  },
  unwrap(result) {
    if (result.success) {
      return result.data;
    }
    throw result.error;
  },
  unwrapOr(result, defaultValue) {
    if (result.success) {
      return result.data;
    }
    return defaultValue;
  }
};

