import { promises as fs2 } from "fs";
import path3 from "path";

// packages/tiny-brain-core/src/utils/commit-parser.ts
function parseCommitMessage(rawCommit) {
  if (!rawCommit || rawCommit.trim() === "") {
    return {
      subject: "",
      body: "",
      fullMessage: rawCommit
    };
  }
  const lines = rawCommit.split("\n");
  const subject = lines[0]?.trim() || "";
  const bodyLines = lines.slice(1);
  let bodyStartIndex = 0;
  for (let i = 0; i < bodyLines.length; i++) {
    if (bodyLines[i].trim() !== "") {
      bodyStartIndex = i;
      break;
    }
  }
  const hasNonEmptyBody = bodyLines.some((line) => line.trim() !== "");
  const body = hasNonEmptyBody ? bodyLines.slice(bodyStartIndex).join("\n").trim() : "";
  return {
    subject,
    body,
    fullMessage: rawCommit
  };
}

// packages/tiny-brain-core/src/utils/adr-pattern-detector.ts
var TRIGGER_KEYWORDS = [
  "adopt",
  "adopting",
  "migrate",
  "migrating",
  "implement",
  "implementing",
  "choose",
  "choosing",
  "replace",
  "replacing",
  "select",
  "selecting"
];
var TECHNOLOGIES = {
  database: ["PostgreSQL", "MySQL", "Redis", "MongoDB", "Cassandra", "DynamoDB"],
  api: ["GraphQL", "REST", "gRPC", "WebSocket"],
  auth: ["OAuth2", "JWT", "SAML", "OpenID"],
  infrastructure: ["Kubernetes", "Docker", "AWS", "GCP", "Azure", "Terraform", "Ansible"],
  messaging: ["Kafka", "RabbitMQ", "NATS", "Redis"],
  frontend: ["React", "Vue", "Angular", "Next.js", "Svelte"]
};
var PATTERNS = [
  "microservices",
  "event-driven",
  "event sourcing",
  "CQRS",
  "hexagonal architecture",
  "clean architecture",
  "API gateway",
  "service mesh",
  "serverless",
  "monolith"
];
function detectADRPatterns(message) {
  const lowerMessage = message.toLowerCase();
  const triggerMatches = [];
  for (const keyword of TRIGGER_KEYWORDS) {
    const regex = new RegExp(`\\b${keyword}\\b`, "i");
    const match3 = lowerMessage.match(regex);
    if (match3 && match3.index !== void 0) {
      triggerMatches.push({ keyword, position: match3.index });
    }
  }
  triggerMatches.sort((a, b) => a.position - b.position);
  const triggers = triggerMatches.map((m) => m.keyword);
  const technologies = [];
  const categories = [];
  for (const [category, techs] of Object.entries(TECHNOLOGIES)) {
    for (const tech of techs) {
      const regex = new RegExp(`\\b${tech}\\b`, "i");
      if (regex.test(message)) {
        if (!technologies.includes(tech)) {
          technologies.push(tech);
        }
        if (!categories.includes(category)) {
          categories.push(category);
        }
      }
    }
  }
  const patterns = [];
  for (const pattern of PATTERNS) {
    const regex = new RegExp(`\\b${pattern}\\b`, "i");
    if (regex.test(lowerMessage)) {
      if (!patterns.includes(pattern)) {
        patterns.push(pattern);
      }
    }
  }
  if (/\bclean\b/i.test(lowerMessage) && !patterns.includes("clean architecture")) {
    patterns.push("clean architecture");
  }
  const hasADRPattern = triggers.length > 0 && (technologies.length > 0 || patterns.length > 0);
  let suggestedTitle = "";
  if (hasADRPattern && triggers.length > 0) {
    const firstTrigger = triggers[0];
    const capitalizedTrigger = firstTrigger.charAt(0).toUpperCase() + firstTrigger.slice(1);
    const firstTech = technologies[0];
    const firstPattern = patterns[0];
    if (firstTech) {
      const fromMatch = message.match(/from\s+(\w+)\s+to\s+(\w+)/i);
      if (fromMatch && technologies.length >= 2) {
        const fromTech = technologies.find(
          (t) => new RegExp(`\\b${t}\\b`, "i").test(fromMatch[1])
        );
        const toTech = technologies.find(
          (t) => new RegExp(`\\b${t}\\b`, "i").test(fromMatch[2])
        );
        if (fromTech && toTech) {
          suggestedTitle = `${capitalizedTrigger} from ${fromTech} to ${toTech}`;
        } else {
          suggestedTitle = `${capitalizedTrigger} ${firstTech}`;
        }
      } else {
        suggestedTitle = `${capitalizedTrigger} ${firstTech}`;
      }
    } else if (firstPattern) {
      const toMatch = new RegExp(`\\b${firstTrigger}\\s+to\\s+${firstPattern}\\b`, "i");
      if (toMatch.test(lowerMessage)) {
        suggestedTitle = `${capitalizedTrigger} to ${firstPattern}`;
      } else {
        suggestedTitle = `${capitalizedTrigger} ${firstPattern}`;
      }
    }
  }
  return {
    hasADRPattern,
    triggers,
    technologies,
    categories,
    patterns,
    suggestedTitle
  };
}

// packages/tiny-brain-core/src/utils/adr-suggestion-generator.ts
function generateADRSuggestion(detection, commit, commitSha) {
  if (!detection.hasADRPattern) {
    return {
      shouldSuggest: false,
      title: "",
      suggestedFileName: "",
      context: "",
      technologies: [],
      categories: [],
      patterns: [],
      commitSha
    };
  }
  const title = detection.suggestedTitle;
  const suggestedFileName = title.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-+|-+$/g, "") + ".md";
  let context = commit.subject;
  if (commit.body) {
    context += `

${commit.body}`;
  }
  return {
    shouldSuggest: true,
    title,
    suggestedFileName,
    context,
    technologies: detection.technologies,
    categories: detection.categories,
    patterns: detection.patterns,
    commitSha
  };
}

